    //
    aIngress = 0xB99C69EB34A25945ULL;
    aCarry = 0xB2C8B25AE70EB24BULL;
    aWandererA = 0xBB06726674782864ULL;
    aWandererB = 0x93AAC3F4F271E778ULL;
    aWandererC = 0xF4DB2EE31CB6BD50ULL;
    aWandererD = 0xBB4801E592E79A7FULL;
