    TwistExpander_Saiph_Arx::SEED_J(PARAMS_SEED);

    TwistExpander_Saiph_Arx::SEED_K(PARAMS_SEED);

    TwistExpander_Saiph_Arx::SEED_L(PARAMS_SEED);

