    TwistExpander_Saiph_Arx::SEED_M(PARAMS_SEED);

    TwistExpander_Saiph_Arx::SEED_N(PARAMS_SEED);

    //
    // [KEY — sixteen key-row functions, lane splits A-P]
    //
    TwistExpander_Saiph_Arx::KEY_A_A(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_A_B(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_A_C(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_A_D(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_A_E(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_A_F(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_A_G(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_A_H(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_B_A(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_B_B(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_B_C(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_B_D(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_B_E(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_B_F(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_B_G(PARAMS_SEED);

    TwistExpander_Saiph_Arx::KEY_B_H(PARAMS_SEED);

    TwistSquash::SquashA(pWorkSpace->mCrystalLaneA, pWorkSpace->mCrystalLaneB, pWorkSpace->mCrystalLaneC, pWorkSpace->mCrystalLaneD, pDestination);

    GrowKeyA(pWorkSpace, ARX_STATE_VARS);

    FoldKeyRowA(pWorkSpace);

    GrowKeyB(pWorkSpace, ARX_STATE_VARS);

    FoldKeyRowB(pWorkSpace);

    pWorkSpace->Zero_PostSeed();

    Zero_PostSeed();
